String money(num v) => NumberFormat.currency(locale: 'en_IN', symbol: '₹', decimalDigits: 0).format(v);

void main() async {
  WidgetsFlutterBinding.ensureInitialized();
  runApp(const InventoryApp(loadDatabase: true));
}

class InventoryApp extends StatelessWidget {
  final bool loadDatabase;
  const InventoryApp({super.key, this.loadDatabase = false});
  @override
  Widget build(BuildContext context) => MaterialApp(
    debugShowCheckedModeBanner: false,
    title: 'Inventory',
    theme: ThemeData(useMaterial3: true, colorSchemeSeed: const Color(0xFF3157E8), scaffoldBackgroundColor: const Color(0xFFF7F8FA), fontFamily: 'Inter', cardTheme: const CardThemeData(elevation: 0, margin: EdgeInsets.zero, color: Colors.white, shape: RoundedRectangleBorder(borderRadius: BorderRadius.all(Radius.circular(20)), side: BorderSide(color: Color(0xFFE8EAF0)))), inputDecorationTheme: InputDecorationTheme(filled: true, fillColor: Colors.white, border: OutlineInputBorder(borderRadius: BorderRadius.circular(16), borderSide: const BorderSide(color: Color(0xFFE8EAF0))), enabledBorder: OutlineInputBorder(borderRadius: BorderRadius.circular(16), borderSide: const BorderSide(color: Color(0xFFE8EAF0))), contentPadding: const EdgeInsets.symmetric(horizontal: 16, vertical: 15))),
    home: AppShell(loadDatabase: loadDatabase),
  );
}

class AppShell extends StatefulWidget {
  final bool loadDatabase;
  const AppShell({super.key, this.loadDatabase = false});
  @override State<AppShell> createState() => _AppShellState();
}
class _AppShellState extends State<AppShell> {
  int index = 0;
  final labels = const ['Home','Inventory','Purchases','Sales','More'];
  final icons = const [Icons.home_outlined,Icons.inventory_2_outlined,Icons.shopping_bag_outlined,Icons.point_of_sale_outlined,Icons.more_horiz];
  @override Widget build(BuildContext context) {
    final pages = [HomePage(loadDatabase: widget.loadDatabase), const InventoryPage(), const PurchasesPage(), const SalesPage(), const MorePage()];
    final wide = MediaQuery.sizeOf(context).width >= 900;
    return Scaffold(body: wide ? Row(children:[NavigationRail(selectedIndex:index,onDestinationSelected:(v)=>setState(()=>index=v),labelType:NavigationRailLabelType.all,leading:const Padding(padding:EdgeInsets.all(20),child:Text('INVENTORY',style:TextStyle(fontWeight:FontWeight.w900))),destinations:[for(var i=0;i<labels.length;i++) NavigationRailDestination(icon:Icon(icons[i]),label:Text(labels[i]))]),const VerticalDivider(width:1),Expanded(child:pages[index])]) : pages[index], bottomNavigationBar: wide ? null : NavigationBar(selectedIndex:index,onDestinationSelected:(v)=>setState(()=>index=v),destinations:[for(var i=0;i<labels.length;i++) NavigationDestination(icon:Icon(icons[i]),label:labels[i])]));
  }
}

