IconData categoryIcon(String s){final c=s.toLowerCase();if(c.contains('mobile'))return Icons.smartphone_outlined;if(c.contains('laptop'))return Icons.laptop_mac_outlined;if(c.contains('television')||c=='tv')return Icons.tv_outlined;if(c.contains('refriger'))return Icons.kitchen_outlined;if(c.contains('air condition'))return Icons.ac_unit_outlined;if(c.contains('washing'))return Icons.local_laundry_service_outlined;if(c.contains('audio'))return Icons.headphones_outlined;if(c.contains('camera'))return Icons.photo_camera_outlined;if(c.contains('printer'))return Icons.print_outlined;if(c.contains('network'))return Icons.router_outlined;if(c.contains('storage'))return Icons.storage_outlined;if(c.contains('gaming'))return Icons.sports_esports_outlined;return Icons.devices_other_outlined;}

