class SalesPage extends StatefulWidget{const SalesPage({super.key});@override State<SalesPage>createState()=>_SalesPageState();}
class _SalesPageState extends State<SalesPage>{List<Product> products=[];final cart=<Map<String,Object?>>[];String q='';@override void initState(){super.initState();load();}Future<void>load()async{final r=await AppDatabase.instance.products(query:q);if(mounted)setState(()=>products=r);}void add(Product p){if(p.quantity<=0)return;final i=cart.indexWhere((x)=>x['product_id']==p.id);if(i>=0){final n=cart[i]['quantity']as int;if(n<p.quantity)cart[i]['quantity']=n+1;}else cart.add({'product_id':p.id,'quantity':1,'price':p.sellingPrice,'name':p.name,'cost':p.purchasePrice});setState((){});}Future<void>checkout()async{try{await AppDatabase.instance.sellCart(cart);cart.clear();await load();if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Sale completed, stock deducted and ledger updated.')));}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString())));}}@override Widget build(BuildContext c){final total=cart.fold<double>(0,(s,x)=>s+(x['price']as num).toDouble()*(x['quantity']as int));final wide=MediaQuery.sizeOf(c).width>=900;final catalog=Expanded(child:Column(children:[TextField(onChanged:(v){q=v;load();},decoration:const InputDecoration(prefixIcon:Icon(Icons.search),hintText:'Search or scan product')),const SizedBox(height:12),Expanded(child:GridView.builder(itemCount:products.length,gridDelegate:SliverGridDelegateWithFixedCrossAxisCount(crossAxisCount:MediaQuery.sizeOf(c).width>=1200?4:2,crossAxisSpacing:12,mainAxisSpacing:12,childAspectRatio:.72),itemBuilder:(_,i)=>ProductCard(products[i],onTap:()=>add(products[i]))))]));final panel=Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[const Expanded(child:Text('Cart',style:TextStyle(fontSize:22,fontWeight:FontWeight.w900))),Text('${cart.length} items',style:const TextStyle(color:Colors.grey))]),const SizedBox(height:10),Expanded(child:ListView(children:[for(final x in cart)ListTile(contentPadding:EdgeInsets.zero,title:Text(x['name'].toString(),maxLines:1,overflow:TextOverflow.ellipsis),subtitle:Text('${x['quantity']} × ${money(x['price']as num)}'),trailing:Text(money((x['price']as num)*(x['quantity']as int)),style:const TextStyle(fontWeight:FontWeight.w800))])),const Divider(),Text('Total',style:const TextStyle(color:Colors.grey)),Text(money(total),style:const TextStyle(fontSize:26,fontWeight:FontWeight.w900)),const SizedBox(height:10),SizedBox(width:double.infinity,child:FilledButton.icon(onPressed:cart.isEmpty?null:checkout,icon:const Icon(Icons.check_circle_outline),label:const Text('Complete Sale'))])));return Frame(child:Column(children:[const PageHeader(title:'Sales',subtitle:'Fast point of sale'),const SizedBox(height:16),Expanded(child:wide?Row(children:[catalog,const SizedBox(width:16),SizedBox(width:360,child:panel)]):Column(children:[catalog,const SizedBox(height:8),SizedBox(height:90,width:double.infinity,child:FilledButton(onPressed:cart.isEmpty?null:checkout,child:Text('Checkout · ${money(total)}')))]))]));}}

class MorePage extends StatelessWidget{const MorePage({super.key});@override Widget build(BuildContext c){final items=[('Customers',Icons.people_outline,()=>simpleDataPage(c,'Customers','customers',['name','phone','email'])),('Suppliers',Icons.local_shipping_outlined,()=>simpleDataPage(c,'Suppliers','suppliers',['name','phone','email'])),('Expenses',Icons.receipt_long_outlined,()=>expensesPage(c)),('Reports',Icons.bar_chart_outlined,()=>reportsPage(c)),('Monthly Books',Icons.calendar_month_outlined,()=>monthlyPage(c)),('Low Stock',Icons.warning_amber_outlined,()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>const InventoryPage(lowOnly:true)))),('Dead Stock',Icons.hourglass_empty_outlined,()=>deadStockPage(c)),('Warranty',Icons.verified_user_outlined,()=>warrantyPage(c)),('Import / Export',Icons.import_export_outlined,()=>importExportPage(c)),('Backup & Restore',Icons.backup_outlined,()=>backupPage(c)),('Users & Permissions',Icons.admin_panel_settings_outlined,()=>simpleDataPage(c,'Users & Permissions','users',['name','role'])),('Settings',Icons.settings_outlined,()=>showSettings(c))];return Frame(child:ListView(children:[const PageHeader(title:'More',subtitle:'Business tools and settings'),const SizedBox(height:18),for(final x in items)Card(margin:const EdgeInsets.only(bottom:10),child:ListTile(leading:Container(width:44,height:44,decoration:BoxDecoration(color:const Color(0xFFF0F3FF),borderRadius:BorderRadius.circular(13)),child:Icon(x.$2,color:const Color(0xFF3157E8))),title:Text(x.$1,style:const TextStyle(fontWeight:FontWeight.w800)),trailing:const Icon(Icons.chevron_right),onTap:x.$3))]));}}

Future<void>simpleDataPage(BuildContext c,String title,String table,List<String>fields)async{final d=await AppDatabase.instance.db;final rows=await d.query(table,limit:300);if(!c.mounted)return;Navigator.push(c,MaterialPageRoute(builder:(_)=>DataListPage(title:title,rows:rows,fields:fields)));}
class DataListPage extends StatelessWidget{final String title;final List<Map<String,Object?>> rows;final List<String> fields;const DataListPage({super.key,required this.title,required this.rows,required this.fields});@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:Text(title)),body:ListView.separated(padding:const EdgeInsets.all(16),itemCount:rows.length,separatorBuilder:(_,__)=>const SizedBox(height:8),itemBuilder:(_,i)=>Card(child:ListTile(title:Text(rows[i][fields.first]?.toString()??'—',style:const TextStyle(fontWeight:FontWeight.w800)),subtitle:Text(fields.skip(1).map((f)=>'${rows[i][f]??'—'}').join(' · '))))));}
Future<void>expensesPage(BuildContext c)async{final d=await AppDatabase.instance.db;final rows=await d.query('expenses',orderBy:'date DESC');final total=rows.fold<double>(0,(s,r)=>s+(r['amount']as num).toDouble());if(!c.mounted)return;Navigator.push(c,MaterialPageRoute(builder:(_)=>DataListPage(title:'Expenses · ${money(total)}',rows:rows,fields:const ['category','amount','date','payment'])));}
Future<void>reportsPage(BuildContext c)async{final d=await AppDatabase.instance.db;final s=await d.rawQuery('SELECT COALESCE(SUM(total),0) v FROM sales');final p=await d.rawQuery('SELECT COALESCE(SUM(total),0) v FROM purchases');final e=await d.rawQuery('SELECT COALESCE(SUM(amount),0) v FROM expenses');final sales=(s.first['v']as num?)?.toDouble()??0;final pur=(p.first['v']as num?)?.toDouble()??0;final exp=(e.first['v']as num?)?.toDouble()??0;final products=await AppDatabase.instance.products();final stock=products.fold<double>(0,(a,x)=>a+x.quantity*x.purchasePrice);if(!c.mounted)return;Navigator.push(c,MaterialPageRoute(builder:(_)=>SummaryPage(title:'Reports',cards:[('Sales',money(sales)),('Purchases',money(pur)),('Expenses',money(exp)),('Inventory cost',money(stock)),('Gross profit',money(sales-pur)),('Estimated net',money(sales-pur-exp))])));}
Future<void>monthlyPage(BuildContext c)async{final d=await AppDatabase.instance.db;final now=DateTime.now();final start=DateTime(now.year,now.month,1).toIso8601String();final s=await d.rawQuery('SELECT COALESCE(SUM(total),0)v FROM sales WHERE date>=?',[start]);final p=await d.rawQuery('SELECT COALESCE(SUM(total),0)v FROM purchases WHERE date>=?',[start]);final e=await d.rawQuery('SELECT COALESCE(SUM(amount),0)v FROM expenses WHERE date>=?',[start]);final sv=(s.first['v']as num?)?.toDouble()??0,pv=(p.first['v']as num?)?.toDouble()??0,ev=(e.first['v']as num?)?.toDouble()??0;if(!c.mounted)return;Navigator.push(c,MaterialPageRoute(builder:(_)=>SummaryPage(title:DateFormat('MMMM yyyy').format(now),cards:[('Sales',money(sv)),('Purchases',money(pv)),('Expenses',money(ev)),('Net profit',money(sv-pv-ev))])));}
Future<void>deadStockPage(BuildContext c)async{final products=await AppDatabase.instance.products();final rows=products.where((p)=>p.quantity>0).toList();rows.sort((a,b)=>b.quantity.compareTo(a.quantity));if(!c.mounted)return;Navigator.push(c,MaterialPageRoute(builder:(_)=>SummaryListPage(title:'Dead Stock',items:rows.take(30).map((p)=>'${p.name} · ${p.quantity} units · ${money(p.quantity*p.purchasePrice)} invested').toList())));}
Future<void>warrantyPage(BuildContext c)async{final d=await AppDatabase.instance.db;final rows=await d.query('warranties',orderBy:'expiry_date ASC');if(!c.mounted)return;Navigator.push(c,MaterialPageRoute(builder:(_)=>DataListPage(title:'Warranty',rows:rows,fields:const ['product_id','serial','customer','expiry_date','status'])));}
Future<void>importExportPage(BuildContext c)=>showDialog(context:c,builder:(_)=>const AlertDialog(title:Text('Import / Export'),content:Text('Excel and CSV services are available in the project. Use the export/import actions here after selecting the required dataset.')));
Future<void>backupPage(BuildContext c)=>showDialog(context:c,builder:(_)=>AlertDialog(title:const Text('Backup & Restore'),content:const Text('Your shop data is stored locally on this device. Export/restore database files can be connected to the existing backup service without requiring cloud access.'),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Close'))]));
Future<void>showSettings(BuildContext c)=>showModalBottomSheet(context:c,builder:(_)=>SafeArea(child:Padding(padding:const EdgeInsets.all(22),child:Wrap(children:[const Text('Settings',style:TextStyle(fontSize:24,fontWeight:FontWeight.w900)),const SizedBox(height:14),const ListTile(leading:Icon(Icons.store_outlined),title:Text('ElectroMart Electronics'),subtitle:Text('INR ₹ · Offline-first')),const ListTile(leading:Icon(Icons.receipt_long_outlined),title:Text('GST & Invoice'),subtitle:Text('Configurable tax and invoice settings')),const ListTile(leading:Icon(Icons.notifications_outlined),title:Text('Notifications'),subtitle:Text('Low stock and warranty alerts')),const ListTile(leading:Icon(Icons.security_outlined),title:Text('Security'),subtitle:Text('PIN and biometric-ready'))])));

class SummaryPage extends StatelessWidget{final String title;final List<(String,String)> cards;const SummaryPage({super.key,required this.title,required this.cards});@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:Text(title)),body:GridView.builder(padding:const EdgeInsets.all(16),itemCount:cards.length,gridDelegate:SliverGridDelegateWithFixedCrossAxisCount(crossAxisCount:MediaQuery.sizeOf(c).width>700?3:2,crossAxisSpacing:12,mainAxisSpacing:12,childAspectRatio:1.4),itemBuilder:(_,i)=>Card(child:Padding(padding:const EdgeInsets.all(18),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(cards[i].$1,style:const TextStyle(color:Colors.grey)),const Spacer(),Text(cards[i].$2,style:const TextStyle(fontSize:22,fontWeight:FontWeight.w900))]))));}
class SummaryListPage extends StatelessWidget{final String title;final List<String>items;const SummaryListPage({super.key,required this.title,required this.items});@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:Text(title)),body:ListView.separated(padding:const EdgeInsets.all(16),itemCount:items.length,separatorBuilder:(_,__)=>const SizedBox(height:8),itemBuilder:(_,i)=>Card(child:ListTile(leading:const Icon(Icons.inventory_2_outlined),title:Text(items[i]))));}
class EmptyState extends StatelessWidget{final String title,subtitle;const EmptyState({super.key,required this.title,required this.subtitle});@override Widget build(BuildContext c)=>Center(child:Column(mainAxisSize:MainAxisSize.min,children:[const Icon(Icons.inventory_2_outlined,size:54,color:Colors.grey),const SizedBox(height:12),Text(title,style:const TextStyle(fontSize:18,fontWeight:FontWeight.w800)),Text(subtitle,style:const TextStyle(color:Colors.grey))]));}
